using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Windows.Forms;
using CastleStorySteam;
sealed partial class InstallerForm {
 string updateMessageKey;object[] updateMessageArgs;
 void SetUpdateInfo(string key,params object[] args){updateMessageKey=key;updateMessageArgs=args;updateInfo.Text=F(key,args);}
 Button checkUpdates=new Button();Label updateInfo=new Label();Timer updateTimer=new Timer();WorkshopSteam steam;
 ulong subscribeCall,queryCall,queryHandle;DateTime updateStarted,nextAutoCheck;bool downloading,downloadFinished,applying,waitingForGame,autoInstallChecked,waitingForWorkshop;int downloadResult;
 void InitializeWorkshopUpdates(){checkUpdates.Text=L("Перевірити оновлення — Steam Workshop");checkUpdates.SetBounds(20,94,620,38);checkUpdates.Click+=delegate{StartWorkshopUpdate();};updateInfo.SetBounds(20,140,620,48);SetUpdateInfo("Програма {0}. Steam перевіряється без запуску гри.",BridgeVersion.Text);Controls.AddRange(new Control[]{checkUpdates,updateInfo});updateTimer.Interval=400;updateTimer.Tick+=WorkshopTick;updateTimer.Start();Shown+=OnUpdatesShown;FormClosed+=delegate{updateTimer.Stop();if(steam!=null)steam.Dispose();};}
 void OnUpdatesShown(object sender,EventArgs e){StartWorkshopUpdate();}
 void StartWorkshopUpdate(){if(!GameGuard.Ready()){waitingForWorkshop=true;SetUpdateInfo("Гра працює або щойно закрилася. Перевірка Workshop чекає завершення гри.");return;}waitingForWorkshop=false;if(!autoInstallChecked){ApplyBundledMod();autoInstallChecked=true;}if(queryCall!=0||subscribeCall!=0||downloading)return;nextAutoCheck=DateTime.UtcNow.AddMinutes(5);try{if(!Setup.IsGame(path.Text))throw new IOException(L("Спочатку обери папку Castle Story."));if(steam==null){steam=new WorkshopSteam(path.Text);steam.DownloadFinished+=delegate(ulong id,int result){if(id==WorkshopChannel.Item){downloadFinished=true;downloadResult=result;}};}checkUpdates.Enabled=false;updateStarted=DateTime.UtcNow;queryHandle=WorkshopSteam.ChannelQuery(WorkshopChannel.OwnerAccount);queryCall=WorkshopSteam.SendQuery(queryHandle);SetUpdateInfo("Шукаю авторський канал оновлень у Steam Workshop…");}catch(Exception e){SetUpdateInfo(e.Message);checkUpdates.Enabled=true;}}
 void WorkshopTick(object sender,EventArgs e){try{if(!GameGuard.Ready()){waitingForWorkshop=true;SetUpdateInfo("Перевірка Workshop відкладена до закриття Castle Story.");return;}if(waitingForWorkshop){waitingForWorkshop=false;StartWorkshopUpdate();}if(steam!=null)WorkshopSteam.RunCallbacks();if(queryCall!=0){if((DateTime.UtcNow-updateStarted).TotalSeconds>60)throw new IOException(L("Steam не відповів на пошук оновлень."));byte[] query=WorkshopSteam.Poll(queryCall,3401,24,8);if(query==null)return;WorkshopChannel.Item=WorkshopSteam.FindChannel(queryHandle,BitConverter.ToUInt32(query,12));WorkshopSteam.ReleaseQuery(queryHandle);queryCall=queryHandle=0;if(WorkshopChannel.Item==0){SetUpdateInfo("Авторський канал оновлень ще не опублікований у Workshop.");checkUpdates.Enabled=true;}else{updateStarted=DateTime.UtcNow;subscribeCall=WorkshopSteam.Subscribe(WorkshopChannel.Item);SetUpdateInfo("Перевіряю підписку й оновлення у Steam Workshop…");}}if(subscribeCall!=0){if((DateTime.UtcNow-updateStarted).TotalSeconds>60)throw new IOException(L("Steam не відповів. Перевір з'єднання та натисни кнопку знову."));byte[] answer=WorkshopSteam.Poll(subscribeCall,1313,16);if(answer==null)return;if(BitConverter.ToUInt64(answer,8)!=WorkshopChannel.Item)throw new IOException(L("Steam повернув іншу підписку."));subscribeCall=0;downloading=true;downloadFinished=false;updateStarted=DateTime.UtcNow;if(!WorkshopSteam.Download(WorkshopChannel.Item,true)){downloading=false;ReadWorkshopRelease();checkUpdates.Enabled=true;}else SetUpdateInfo("Steam перевіряє та завантажує файли оновлення…");}
  if(downloading){if((DateTime.UtcNow-updateStarted).TotalMinutes>10)throw new IOException(L("Завантаження ще не завершено. Перевір завантаження Steam."));ulong received,total;if(WorkshopSteam.Progress(WorkshopChannel.Item,out received,out total)&&total>0)SetUpdateInfo("Завантаження Workshop: {0} %",(100.0*received/total).ToString("F0"));if(downloadFinished||WorkshopSteam.Folder(WorkshopChannel.Item)!=null){if(downloadFinished&&downloadResult!=1)throw new IOException(F("Steam не завершив завантаження: код {0}",downloadResult));if(WorkshopSteam.Folder(WorkshopChannel.Item)==null)return;downloading=false;ReadWorkshopRelease();checkUpdates.Enabled=true;}}
  if(!autoInstallChecked&&!downloading&&subscribeCall==0&&queryCall==0){autoInstallChecked=true;ApplyBundledMod();}if(waitingForGame&&GameGuard.Ready()){waitingForGame=false;ApplyBundledMod();}if(steam!=null&&queryCall==0&&subscribeCall==0&&!downloading&&DateTime.UtcNow>=nextAutoCheck)StartWorkshopUpdate();
 }catch(Exception error){if(queryHandle!=0)WorkshopSteam.ReleaseQuery(queryHandle);queryCall=queryHandle=subscribeCall=0;downloading=false;nextAutoCheck=DateTime.UtcNow.AddMinutes(5);checkUpdates.Enabled=true;SetUpdateInfo(error.Message);}}
 void ReadWorkshopRelease(){string folder=WorkshopSteam.Folder(WorkshopChannel.Item);if(folder==null)throw new IOException(L("Steam ще не встановив файли Workshop. Спробуй знову."));string file=Path.Combine(folder,"program.csupdate");FileInfo info=new FileInfo(file);if(!info.Exists||info.Length>DesktopRelease.MaxBytes)throw new IOException(L("Пакет оновлення Workshop відсутній або некоректний."));string version;byte[] app,sig;DesktopRelease.Parse(File.ReadAllBytes(file),out version,out app,out sig);if(!UpdateVerifier.IsNewer(version,BridgeVersion.Text)){SetUpdateInfo("Програма {0}. Новішої підписаної версії у Workshop немає.",BridgeVersion.Text);return;}string next=DesktopRelease.Store(DesktopRelease.CacheRoot,version,app,sig),game=path.Text;SetUpdateInfo("Оновлення {0} перевірене. Відкриваю нову програму…",version);Process.Start(new ProcessStartInfo(next,DesktopRelease.Quote(game)){UseShellExecute=false});Close();}
 void ApplyBundledMod(){if(applying)return;applying=true;try{int state=AutoModUpdate.Apply(path.Text,!GameGuard.Ready());if(state==-1){waitingForGame=true;result.Text=L("Нове оновлення готове. Закрий Castle Story — тоді файли мода оновляться.");}else if(state==1)result.Text=F("Мод оновлено до {0}. Налаштування й резервні копії збережено.",BridgeVersion.Text);}finally{applying=false;}}
}
